-- TacticalSlots -- generated by Rime ui_build_mod. Edit the screen document and rebuild; do not edit this file.
--
-- Ships the mod's superbundle. A UI resource has to be mounted BEFORE the pass that binds it:
--   . the level's MAIN pass binds widget movies (ui/assets/<widget>)          -> PREPEND there
--   . the <level>_UiPlaying pass is where screen movies resolve (at push time) -> APPEND there
-- Guard of three conditions: superbundle mounted this level + '_uiplaying' + the CURRENT level name, because
-- the frontend has a _UiPlaying pass of its own and injecting there hangs the client on a black screen.
-- Shared on purpose: the server never matches these passes.

local SUPERBUNDLE = "tacticalslotsui/ui"
local BUNDLE = "tacticalslotsui/uibundle"
-- the mod's pictures: their texture headers ride in the bundle, their pixels in this chunk store (empty = no pictures)
local CHUNKS = "tacticalslotsui/chunks"

local m_Mounted = false

local function LOG(p_Text)
	if _G.TACTICALSLOTS_PRINTS then
		print("[TacticalSlots/sb] " .. tostring(p_Text))
	end
end

Events:Subscribe("Level:LoadResources", function()
	m_Mounted = pcall(function() ResourceManager:MountSuperBundle(SUPERBUNDLE) end)
	LOG("level starting -- superbundle mounted: " .. tostring(m_Mounted))
	if CHUNKS ~= "" then
		local s_Chunks = pcall(function() ResourceManager:MountSuperBundle(CHUNKS) end)
		LOG("picture chunk store mounted: " .. tostring(s_Chunks))
	end
end)

Hooks:Install("ResourceManager:LoadBundles", 100, function(p_Hook, p_Bundles, p_Compartment)
	local s_Names = {}
	for _, l_Name in ipairs(p_Bundles) do
		s_Names[#s_Names + 1] = tostring(l_Name)
	end

	local s_Level = ""
	pcall(function() s_Level = string.lower(tostring(SharedUtils:GetLevelName() or "")) end)

	if not m_Mounted or s_Level == "" or string.find(s_Level, "frontend", 1, true) ~= nil then
		return
	end

	local s_IsMain = false
	local s_IsUiPlaying = false
	for _, l_Name in ipairs(s_Names) do
		local l_Lower = string.lower(l_Name)
		if l_Lower == s_Level then
			s_IsMain = true
		end
		if string.find(l_Lower, "_uiplaying", 1, true) ~= nil and string.find(l_Lower, s_Level, 1, true) ~= nil then
			s_IsUiPlaying = true
		end
		if l_Name == BUNDLE then
			return -- already ours; never inject twice into the same call
		end
	end

	if s_IsMain then
		local s_First = { BUNDLE }
		for _, l_Name in ipairs(p_Bundles) do
			s_First[#s_First + 1] = l_Name
		end
		LOG("prepending our bundle to the MAIN level pass")
		p_Hook:Pass(s_First, p_Compartment)
		return
	end

	if s_IsUiPlaying then
		local s_New = {}
		for _, l_Name in ipairs(p_Bundles) do
			s_New[#s_New + 1] = l_Name
		end
		s_New[#s_New + 1] = BUNDLE
		LOG("appending our bundle to the UiPlaying pass")
		p_Hook:Pass(s_New, p_Compartment)
	end
end)
